import asyncio


async def double(ms):
    await asyncio.sleep(ms / 1000)
    return ms * 2


async def main(delays):
    return list(await asyncio.gather(*(double(d) for d in delays)))


def double_all(delays):
    return asyncio.run(main(delays))

